mapper.select:
SELECT target.target_id AS id, target.task_id, target.target_name, target.target_code, target.target_category as target_type, target.status, target.target_code, target.area_name, target.location, target.target_lnt_and_lat, target.rule_id FROM daily_task_target_ref ref INNER JOIN daily_task_target target ON ref.target_ref_id = target.id
AND target.status = #{param.status}
AND target.tag_ids like CONCAT('%',#{param.tagId},'%')
AND target.target_category = #{param.targetType}
AND target.target_name LIKE CONCAT('%',#{param.keyword},'%')
AND ref.task_id IN
#{taskId}
AND ref.task_id = #{param.taskId}
AND target.target_id IN
#{targetId}
ORDER BY target.status DESC, target.distributed ASC, target.id DESC

SELECT dt.id AS task_id, dt.`name` AS task_name, dat.target_id, dat.target_name, dat.area_name, dat.location FROM daily_task_target dat LEFT JOIN daily_task_target_ref datr ON datr.target_ref_id = dat.id LEFT JOIN daily_task dt ON dt.id = datr.task_id LEFT JOIN daily_task_user dtu ON dtu.master_id = datr.task_id WHERE dat.target_id IN
#{targetId}
AND dat.`status` = 'WAIT' AND dt.`status` = 'WAIT' AND dtu.target_id = #{userId} GROUP BY dt.id
